        connectedPeers: discv5.connectedPeerCount,
        activeSessions: discv5.sessionService.sessionsSize(),
        ip4Nodes: ip4Only,
        ip6Nodes: ip6Only,
        ip4AndIp6Nodes: ip4ip6,
        unreachableNodes: unreachable,
